  "summary": "都市白领许红豆在闺蜜病逝后辞职前往云南大理云苗村短住，在民宿老板谢之遥与当地村民的陪伴下重新找到生活的节奏与内心的安宁。剧集摒弃了强冲突叙事以慢节奏呈现乡村日常的治愈力量，同时不回避返乡创业的现实困境与城乡差距的真实存在。刘亦菲与李现的表演松弛自然毫无表演痕迹让这部剧成为后疫情时代都市人的精神避难所。氛围营造极佳真正拍出了'风'的感觉与地方的呼吸，剧情推动力较弱依赖氛围支撑，但这恰恰是其美学选择。国产剧少有的真正治愈系作品，看完会想买一张去大理的车票。",
