  "summary": "抗战末期滇西战场，一群溃兵在冒牌团长龙文章的带领下重组为川军团，参与惨烈的南天门战役。剧集摒弃英雄主义叙事，聚焦战争中个体的恐惧、懦弱与尊严，以粗粝真实的影像风格呈现远征军的苦难与牺牲。台词充满哲学思辨，角色群像复杂深刻，虽播出时收视不佳，后被公认为中国战争剧的思想高峰。",
  "review": "被低估的神作，中国战争剧的灵魂之作。",
