  "summary": "一艘殖民飞船坠毁在一颗充满奇异生态的外星球上，幸存者们分裂为不同派系，在陌生环境中挣扎求生。两名年轻的拾荒者在废墟中发现了一个可能改变所有人命运的秘密，由此踏上一段穿越异星荒野的危险旅程。HBO出品的这部成人动画以惊人的世界观构建与视觉想象力，探讨了文明崩溃后人类如何重建秩序与意义，叙事大胆而不妥协，是近年最具原创性的科幻动画作品。",
