  "summary": "BBC出品的伪纪录片式喜剧，由Philomena Cunk以一本正经的荒诞提问重新审视人类文明史。节目邀请牛津、剑桥等顶尖学府的真实专家学者回答诸如'金字塔是不是外星人建的''文艺复兴是不是因为大家突然想画画''耶稣会不会发推特'等无厘头问题，专家们被迫在学术严谨与主持人的天真无知之间艰难周旋。节目在解构权威历史叙事的同时揭示了历史认知的建构性与不确定性，笑点密集且智识含量极高。这种形式创新彻底颠覆了传统历史纪录片的严肃范式，用最不正经的方式讲最严肃的事，是知识类喜剧当之无愧的天花板之作。",
  "review": "用最不正经的方式讲最严肃的事，是知识类喜剧的天花板。",
