  "summary": "《扯淡地球史》姊妹篇，聚焦英国本土历史脉络。主持人Philomena Cunk以天真无知的人设走访大英博物馆、议会大厦、巨石阵等地标，向专家提出令人啼笑皆非的问题，从罗马入侵、诺曼征服到工业革命、脱欧乱象全程覆盖。节目以反讽手法戳破大英帝国叙事的虚伪与自恋，同时展现了英国人对自身历史根深蒂固的自嘲精神。本土化梗比地球史更密集，讽刺力度也更强，专家的冷面回应与主持人的荒诞提问制造出绝佳的反差喜感。对英国历史不熟悉的观众理解成本略高，但即便如此仍能感受到那种独特的英式幽默节奏与文化自省态度。",
  "review": "比地球史更聚焦也更辛辣，是了解英国人自黑文化的绝佳入口。",
